<?php require 'includes/bootstrap.php';require_login();$page_title='Избранное';$favoriteIds=favorite_ids($pdo);$s=$pdo->prepare('SELECT p.* FROM properties p JOIN favorites f ON f.property_id=p.id WHERE f.user_id=? ORDER BY f.created_at DESC');$s->execute([user()['id']]);$properties=$s->fetchAll();require 'includes/header.php'; ?><main class="container section"><p class="eyebrow">Ваша сохранённая коллекция</p><h1>Избранное</h1><?php if($properties): ?><div class="property-grid"><?php foreach($properties as $p)require 'includes/property-card.php';?></div><?php else:?><div class="empty"><h2>Вы ещё не сохранили ни одного объекта.</h2><a class="button" href="catalog.php">Перейти в каталог</a></div><?php endif?></main><?php require 'includes/footer.php'; ?>
